function formatIsoString(isoString) {
    const match = isoString.match(/(\.\d+)(Z)$/);
    if (match) {
        let milliseconds = match[1];
        let digits = milliseconds.substring(1);

        if (digits.length < 3) {
            milliseconds = `.${digits.padEnd(3, '0')}`;
        } else if (digits.length > 3) {
            milliseconds = `.${digits.substring(0, 3)}`;
        }

        return isoString.replace(/(\.\d+)(Z)$/, `${milliseconds}$2`);
    }
    return isoString;
}

function formatComments(items, parentName) {
    if (!items.length) return '';
    return items.map(item => {
